import { TourRoot, TourAnchor, TourTrigger, type TourStepDef } from "@/components/bevelui/tour";

const steps: TourStepDef[] = [
  {
    step: 1,
    title: "Your profile",
    description: "Click here to update your avatar and display name.",
    side: "bottom",
  },
  {
    step: 2,
    title: "Settings",
    description: "Manage notifications, billing, and team members here.",
    side: "right",
  },
];

export default function DashboardPage() {
  return (
    <TourRoot steps={steps} defaultOpen>
      <TourAnchor step={1}>
        <Avatar />
      </TourAnchor>

      <TourAnchor step={2} asChild>
        <button>Settings</button>
      </TourAnchor>

      <TourTrigger label="Take a tour" />
    </TourRoot>
  );
}

const steps: TourStepDef[] = [
  {
    step: 1,
    title: "Export your data",
    description: "Click the export button to download a CSV.",
    side: "bottom",
    media: {
      type: "video",           // "video" | "gif" | "image"
      src: "/demos/export.mp4",
      poster: "/demos/export-thumb.jpg",
    },
  },
];

import { useTour } from "@/components/bevelui/tour";

function MyToolbar() {
  const {
    start, stop, next, prev,
    skip, goTo, currentStep,
    totalSteps, isOpen
  } = useTour();

  return (
    <div>
      <button onClick={start}>Start tour</button>
      <button onClick={() => goTo(3)}>Jump to step 3</button>
      <button onClick={skip}>Skip</button>
      <span>{currentStep} / {totalSteps}</span>
    </div>
  );
}
